    # GIVEN an immutable list with one element
    list_with_one_element = immutable_list.ImmutableList(10)

    # WHEN adding another empty list
    result = list_with_one_element.__add__(immutable_list.ImmutableList())

    # THEN verify the resulting list has the same elements
    assert result == immutable_list.ImmutableList(10), "The resulting list should have the same elements"

    # AND that the lists are different instances
    assert result is not list_with_one_element, "The original and resulting lists should be different instances"

    # GIVEN an immutable list with multiple elements
    list_with_multiple_elements = immutable_list.ImmutableList(10, 20, 30)

    # WHEN adding another list with multiple elements
    result = list_with_multiple_elements.__add__(immutable_list.ImmutableList(40, 50))

    # THEN verify the resulting list has all the elements
    assert result == immutable_list.ImmutableList(10, 20, 30, 40, 50), "The resulting list should have all the elements"

    # AND that the lists are different instances
    assert result is not list_with_multiple_elements, "The original and resulting lists should be different instances"

