def test_map_function_applies_function_to_all_elements():
    """
    This test case is designed to verify that the map function correctly applies the provided function to all elements in the ImmutableList.

    Setup:
    1- Created an empty ImmutableList.

    Execution:
    2- Used the map function to apply another function that reverses the string representation of all list elements.
    3- Converted the modified ImmutableList back to a list.

    Assertion:
    4- Verified that the resultant list contains the reversed string representations of all elements from the original list.
    """

    EMPTY_IMMUTABLE_LIST = immutable_list.ImmutableList(is_empty=True)
    LIST_ELEMENTS = ['123', '456', '789']
    REVERSE_STRING = lambda x: x[::-1]

    immutable_list_ = EMPTY_IMMUTABLE_LIST
    for element in LIST_ELEMENTS:
        immutable_list_ = immutable_list.ImmutableList(element, immutable_list_)

    modified_immutable_list = immutable_list_.map(REVERSE_STRING)
    modified_list = modified_immutable_list.to_list()

    assert modified_list == list(map(REVERSE_STRING, LIST_ELEMENTS))

