def test_push_and_append_and_find_new():
    # Given
    NUM_ZERO = 0
    empty_list = immutable_list.ImmutableList(is_empty=True)

    # When a new element is unshifted on to the empty list
    result_list = empty_list.unshift(NUM_ZERO)

    # Then the resulting list should have one element
    assert len(result_list) == 1

    # And the first element of the resulting list should be NUM_ZERO
    assert result_list[0] == NUM_ZERO

    # When a new element is appended to the end of the result_list
    further_result_list = result_list.append(result_list)

    # Then the further_result_list should have two elements
    assert len(further_result_list) == 2

    # And the last element of the further_result_list should also be NUM_ZERO
    assert further_result_list[1] == NUM_ZERO

    # When we use the find method in further_result_list to find an element that matches NUM_ZERO
    # Then the first matching element should be NUM_ZERO
    assert further_result_list.find(lambda x: x == NUM_ZERO) == NUM_ZERO

    # Similarly, all elements of further_result_list should be NUM_ZERO
    assert all(element == NUM_ZERO for element in further_result_list)

