def test_immutable_list_operations_updated():
    """
    This test case checks the functionality of the ImmutableList
    class. It creates a new instance of ImmutableList, appends, 
    reduces, checks for equality, and adds elements to the unshift
    of another instance of ImmutableList. It then checks if an 
    empty instance of ImmutableList is equivalent to an empty 
    instance of ImmutableList. The instance is then used to find
    a certain value. Finally, the ImmutableList object is converted
    to a string and printed.
    """

    # Setup: Create initial instances of ImmutableList
    immutable_list_0 = ImmutableList()
    immutable_list_1 = immutable_list_0.append(immutable_list_0)

    # Execution: Perform operations on ImmutableLists
    var_0 = immutable_list_0.reduce(immutable_list_1, immutable_list_1)
    bool_0 = immutable_list_1.__eq__(immutable_list_0)
    immutable_list_2 = immutable_list_1.unshift(immutable_list_1)
    str_0 = immutable_list_2.__str__()
    immutable_list_3 = ImmutableList(is_empty=str_0)
    immutable_list_4 = var_0.append(var_0)

    # Assertion: Verify the result of the operations
    assert bool_0 == False
    assert immutable_list_2.find(var_0) == var_0
    assert immutable_list_0.is_empty == immutable_list_3.is_empty

def test_reduce_function_executes_correctly():
    # Setup
    EMPTY_LIST = immutable_list.ImmutableList()
    INITIAL_ELEMENT = immutable_list.ImmutableList()
    immutable_list_0 = immutable_list.ImmutableList(INITIAL_ELEMENT, EMPTY_LIST)

    # Execution
    immutable_list_1 = immutable_list_0.unshift(INITIAL_ELEMENT)
    var_0 = immutable_list_0.reduce(immutable_list_1, immutable_list_1)
    list_length = immutable_list_1.__len__()
    immutable_list_2 = immutable_list_1.unshift(immutable_list_1)
    bool_0 = immutable_list_2.__eq__(immutable_list_0)
    var_1 = immutable_list_2.find(lambda x: x % 2 == 0)

    # Assertion
    assert EMPTY_LIST == immutable_list_0, "List should be empty initially"
    assert var_0 is not None, "reduce function must not return None"
    assert list_length == 2, "Length of the list should be 2 after unshift"
    assert not bool_0, "Lists should not be equal"
    assert var_1 is None, "No even number in the list"

